import test from 'node:test';
import assert from 'node:assert/strict';
import { once } from 'node:events';
import { createHmac } from 'node:crypto';
import WebSocket from 'ws';
import { createOverlayFixture } from '../test-support/overlay-fixture.js';
import { createOverlayFeed } from '../src/overlay-feed.js';
import { createMemoryState } from '../src/state.js';
import { connectOverlay } from '../public/overlay-client.js';

const origin = 'http://127.0.0.1:5191';
function inbox(ws) {
  const messages = []; const waiters = [];
  ws.on('message', bytes => { const value = JSON.parse(bytes); if (value.type !== 'snapshot') return;
    if (waiters.length) waiters.shift()(value); else messages.push(value); });
  return () => messages.length ? Promise.resolve(messages.shift()) : new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Snapshot timeout')), 2000);
    waiters.push(value => { clearTimeout(timer); resolve(value); });
  });
}
async function socket(t) {
  const ws = new WebSocket(`${origin.replace('http', 'ws')}/ws/111`, { origin }); const next = inbox(ws);
  t.after(() => ws.terminate()); await once(ws, 'open'); return { ws, next };
}
async function local(t, options) {
  const fixture = await createOverlayFixture(options); t.after(() => fixture.close());
  try { await fixture.listen(); }
  catch (error) { if (error.code !== 'EPERM') throw error; t.skip('Sandbox denies loopback listen on fixed 127.0.0.1:5191 (EPERM)'); return null; }
  return fixture;
}
test('public HTTP and real WebSocket deliver safe initial state, signed-event updates, moderation and immediate forget removal', async t => {
  const f = await local(t); if (!f) return; const { next } = await socket(t);
  assert.equal((await next()).status, 'waiting');
  await f.app.marks.setKeeperContext('111', { streamId: 'test-explicit-stream', keeperId: '111', optedIn: true, holdsRelic: true, blockedUserIds: [] });
  assert.equal((await next()).approvedCount, 0);
  const timestamp = new Date().toISOString(); const id = 'signed-overlay-test';
  const body = JSON.stringify({ subscription: { type: 'channel.chat.message', version: '1', condition: { broadcaster_user_id: '111', user_id: '222' } },
    event: { broadcaster_user_id: '111', chatter_user_id: '987654321', message_id: 'private-message-id', badges: [], message: { text: '!mark orchid', fragments: [{ type: 'text', text: '!mark orchid' }] } } });
  const signature = createHmac('sha256', 'synthetic-overlay-test-secret').update(id).update(timestamp).update(body).digest('hex');
  const response = await fetch(`${origin}/eventsub`, { method: 'POST', body, headers: { 'twitch-eventsub-message-id': id,
    'twitch-eventsub-message-timestamp': timestamp, 'twitch-eventsub-message-type': 'notification', 'twitch-eventsub-message-signature': `sha256=${signature}` } });
  assert.equal(response.status, 204); assert.equal((await next()).marks.length, 0);
  await f.app.marks.approve('111', f.admin, 'm1'); const approved = await next(); assert.equal(approved.marks.length, 1);
  const snapshot = await (await fetch(`${origin}/api/overlay/111`)).json();
  assert.deepEqual(snapshot, approved);
  const serialized = JSON.stringify(snapshot);
  for (const forbidden of ['orchid', '987654321', 'private-message-id', 'userId', 'spent', 'token', 'cooldown']) assert.ok(!serialized.includes(forbidden));
  await f.app.marks.forgetMe('111', { broadcasterId: '111', chatterId: '987654321' });
  const forgotten = await next(); assert.equal(forgotten.marks.length, 0); assert.ok(forgotten.revision > approved.revision);
  await f.app.marks.approve('111', f.admin, 'm1'); assert.equal((await next()).marks.length, 0);
  for (const path of ['/api/overlay/222', '/overlay/222', '/marks/approve']) assert.equal((await fetch(origin + path)).status, 404);
  assert.equal((await fetch(`${origin}/api/overlay/111`, { method: 'POST' })).status, 404);
  assert.match(await (await fetch(`${origin}/overlay/111`)).text(), /0 growth rings/);
});
test('reconnect obtains current snapshot and socket messages cannot mutate state', async t => {
  const f = await local(t, { seed: true }); if (!f) return; const { ws, next } = await socket(t);
  assert.equal((await next()).approvedCount, 8);
  const closed = once(ws, 'close'); ws.send('approve m99'); assert.equal((await closed)[0], 1008);
  await f.app.marks.vetoLast('111', f.admin);
  const second = await socket(t); assert.equal((await second.next()).approvedCount, 7);
});
test('upgrade channel/path/origin and client resource limits are enforced', async t => {
  if (!await local(t, { socketOptions: { maxClients: 1 } })) return; const first = await socket(t); await first.next();
  async function rejected(path, requestOrigin) {
    await new Promise((resolve, reject) => {
      const ws = new WebSocket(`ws://127.0.0.1:5191${path}`, { origin: requestOrigin });
      ws.on('error', () => {});
      ws.on('unexpected-response', (_req, response) => { assert.equal(response.statusCode, 403); response.resume(); ws.terminate(); resolve(); });
      ws.on('open', () => { ws.terminate(); reject(new Error('Unexpected upgrade')); });
    });
  }
  await rejected('/ws/222', origin); await rejected('/ws/111?control=1', origin);
  await rejected('/ws/111', 'https://evil.example'); await rejected('/ws/111', origin);
});
