  if (!await local(t, { socketOptions: { heartbeatMs: 30 } })) return;
  const { ws, next } = await socket(t); await next(); const closed = once(ws, 'close'); ws.send('x'.repeat(1025)); assert.equal((await closed)[0], 1009);
  const silent = new WebSocket('ws://127.0.0.1:5191/ws/111', { origin, autoPong: false });
  silent.on('error', () => {}); t.after(() => silent.terminate());
  await once(silent, 'open'); await once(silent, 'close');
