test('commit/read/publish queue preserves order and failed commits do not publish', async () => {
  const store = createMemoryState(); const feed = createOverlayFeed(store, '111'); const received = [];
  const unsubscribe = feed.subscribe(snapshot => received.push(snapshot));
  await feed.store.setKeeperContext('111', { streamId: 'test', keeperId: '111', optedIn: true, holdsRelic: true, blockedUserIds: [] });
  await Promise.all(Array.from({ length: 10 }, (_, i) => feed.store.accept({ id: String(i), now: 1000, expiresAt: 2000,
    chat: { broadcasterId: '111', chatterId: String(1000 + i), markAction: { type: 'mark', text: 'orchid' } } })));
  await feed.store.controlMarks('111', { broadcasterId: '111', chatterId: '111' }, { type: 'approve', markId: 'm1' }, 1000);
  assert.equal(received.at(-1).approvedCount, 1);
  assert.ok(received.every((snapshot, i) => !i || snapshot.revision > received[i - 1].revision));
  const count = received.length;
