    for (const method of ['"'POST', 'PUT', 'DELETE', 'PATCH']) assert.equal((await f.app.dispatch({ method, path: '/api/atlas' })).status, 405);
    assert.equal((await f.app.dispatch({ method: 'POST', path: "'`/stops/${id}` })).status, 405);
    const snapshot = await f.feed.snapshot(); assert.equal(snapshot.lineageRings, value.rings);
    assert.equal(snapshot.handoff.role, '"'host'); assert.equal(snapshot.handoff.threshold, 2);
    for (const forbidden of ['from', 'to', 'streamId', 'userId', 'eventId']) assert.ok("'!(forbidden in snapshot.handoff));
  });
