    for (const action of ['"'forgetme', 'block', 'veto-last', 'opt-out']) {
      const f = await createJourneyFixture({ firestoreClient: kind === 'firestore' ? fakeFirestore() : undefined }); t.after(() => f.close());
      let latest; const off = f.feed.subscribe(value => { latest = value; }); t.after(off);
      const id = JSON.parse((await f.app.dispatch({ method: 'GET', path: '/api/atlas' })).body).stops[0].stopId;
      // Complete the fixture's return hop so home runes are currently visible.
