      await f.chat(f.source, '7003', { type: 'accept' }); await f.chat(f.source, '7004', { type: 'accept' });
      assert.equal(latest.approvedCount, 4); assert.equal(latest.lineageRings, 2);
      const actor = { broadcasterId: f.source, chatterId: action === 'forgetme' ? '9000' : f.source };
      await f.state.controlMarks(f.source, actor, { type: action, userId: '9000' }, Date.now());
