  const hop = { role: 'host', startedAt: 1000, endsAt: 91000 };
  for (const [now, phase] of [[999, 'idle'], [1000, 'streak'], [3999, 'streak'], [4000, 'impact'], [6000, 'unfurl'], [20999, 'unfurl'], [21000, 'settled'], [91000, 'idle']]) assert.equal(arrivalPhase(hop, now).phase, phase);
  assert.equal(arrivalPhase(hop, 12000).phase, 'unfurl'); assert.equal(arrivalPhase(hop, 2000, true).phase, 'settled');
